"""
Write a JavaScript program that returns the sum of the first n numbers.
"""

function findSum(n) {
    let sum = 0;
    for(let i = 0; i <= n; i++) {
        sum += i;
    }
    return sum;
}

if (typeof module !== 'undefined') {
    module.exports = findSum;
}

console.log(findSum(10)); // 55

